#include<bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){ int seed=argc>1?atoi(argv[1]):170833;mt19937 rng(seed);string p="research/mixed_tier17_order8_20261105/cache/anneal_";ifstream io(p+"origin.bin",ios::binary|ios::ate);int n=io.tellg();io.seekg(0);vector<uint8_t> origin(n);io.read((char*)origin.data(),n);ifstream ie(p+"edges.bin",ios::binary|ios::ate);long long m=ie.tellg();m/=8;ie.seekg(0);vector<vector<int>> adj(n);for(long long k=0;k<m;k++){int a,b;ie.read((char*)&a,4);ie.read((char*)&b,4);if(a<0||a>=n||b<0||b>=n)return 2;adj[a].push_back(b);adj[b].push_back(a);}vector<uint8_t>sel(n);vector<int>cnt(n),tabu(n),bestsel;int cur=0,best=accumulate(origin.begin(),origin.end(),0);auto insert=[&](int i){sel[i]=1;cur++;for(int j:adj[i])cnt[j]++;};auto remove=[&](int i, vector<int>&z,int it){sel[i]=0;cur--;tabu[i]=it+7+rng()%25;for(int j:adj[i]){cnt[j]--;if(!sel[j]&&!cnt[j])z.push_back(j);}};auto reset=[&](){fill(sel.begin(),sel.end(),0);fill(cnt.begin(),cnt.end(),0);fill(tabu.begin(),tabu.end(),0);cur=0;for(int i=0;i<n;i++)if(origin[i]){if(cnt[i]){cerr<<"source conflict"<<endl;exit(2);}insert(i);}};reset();cout<<"n "<<n<<" edges "<<m<<" start "<<cur<<endl;
for(int it=1;it<=20000000;it++){int pick=-1,bc=999;for(int t=0;t<512;t++){int q=rng()%n;if(sel[q]||tabu[q]>it)continue;int score=cnt[q]+(rng()%1000<70?int(rng()%3):0);if(score<bc){bc=score;pick=q;}}if(pick<0)continue;if(cnt[pick]>3 && rng()%100 < (cnt[pick]<=10 ? 65 : cnt[pick]<=30 ? 90 : 98))continue;vector<int> victims,zero;for(int j:adj[pick])if(sel[j])victims.push_back(j);for(int j:victims)remove(j,zero,it);insert(pick);shuffle(zero.begin(),zero.end(),rng);for(int j:zero)if(!sel[j]&&!cnt[j]&&tabu[j]<=it)insert(j);if(cur>best){best=cur;cout<<"BEST "<<best<<" iteration "<<it<<endl;ofstream f(p+"potential.bin",ios::binary);f.write((char*)sel.data(),n);return 0;}if(cur<best-80)reset();if(it%100000==0)cout<<"progress "<<it<<" size "<<cur<<" best "<<best<<endl;}
}
